    "url": "https://www.w3schools.com/python/python_regex.asp",
    "idea": "A regular expression is a search pattern. Think of looking for every toy with a red stripe rather than one exact toy. The re module can find text matching a pattern. A digit pattern can find numbers. Start with small patterns, because a complicated pattern can be hard to read and easy to misunderstand.",
    "code": "import re\nprint(re.findall(r\"\\d+\", \"I have 12 blocks and 3 cars\"))",
