    "idea": "Quick sort chooses a pivot and separates smaller and larger values around it. Think of dividing toy blocks by comparing them with one chosen block. Sort the smaller and larger groups in the same way, then combine them. Pivot choices affect speed. This readable version builds new lists; many practical implementations rearrange in place.",
    "code": "def quick(values):\n    if len(values) < 2: return values\n    pivot = values[len(values) // 2]\n    small = [x for x in values if x < pivot]\n    equal = [x for x in values if x == pivot]\n    large = [x for x in values if x > pivot]\n    return quick(small) + equal + quick(large)\nprint(quick([3, 1, 2]))",
