    "idea": "Radix sort organizes numbers one digit position at a time. Think of sorting number cards by the ones digit, then tens, then hundreds. Each pass must keep the previous order within a digit group. This stable order lets the passes work together. The example sorts nonnegative integers. Other types need additional rules.",
    "code": "numbers = [21, 13, 2, 11]\nplace = 1\nwhile max(numbers) // place > 0:\n    buckets = [[] for _ in range(10)]\n    for number in numbers:\n        buckets[(number // place) % 10].append(number)\n    numbers = [number for bucket in buckets for number in bucket]\n    place *= 10\nprint(numbers)",
