    "idea": "Merge sort splits a collection into smaller halves, sorts those halves, and merges the ordered results. Think of arranging two small card piles, then taking the smaller front card from either pile to build one ordered row. A one-item pile is already sorted. This is a divide-and-combine strategy.",
    "code": "def merge_sort(values):\n    if len(values) < 2: return values\n    middle = len(values) // 2\n    left = merge_sort(values[:middle])\n    right = merge_sort(values[middle:])\n    result = []\n    i = j = 0\n    while i < len(left) and j < len(right):\n        if left[i] <= right[j]:\n            result.append(left[i]); i += 1\n        else:\n            result.append(right[j]); j += 1\n    return result + left[i:] + right[j:]\nprint(merge_sort([3, 1, 2]))",
    "question": "What is first after sorting?",
    "answers": [
      "1"
    ],
    "steps": [
      "Split until each part is very small.",
      "Sort the halves recursively.",
      "Merge by repeatedly taking the smaller front value."
    ],
    "note": "Learn lists, loops, and functions before this section. This lesson introduces the idea with a small example.",
